package corpus; import java.util.List; interface Named { String name(); } record Item<T>(T value) {} enum Mode { ON, OFF } class CoreDeclarations<T extends Number & Comparable<T>> implements Named { private final List<? extends T> values; CoreDeclarations(List<? extends T> values) { this.values = values; } public String name() { return "core"; } <U> U echo(U value) { return value; } }
